example.source:
ja certifier 0.3
module corpus.ja_certifier.example_01251
policy no_execute_unknown_code
policy no_network
grammar Grammar01251 {
  mode DEFAULT { token IDENT = letter, { letter | digit } ; }
  precedence left "+" "-" level 10 ;
  precedence left "*" "/" level 20 ;
  production expression @ast(BinaryExpr) = expression, operator, expression | IDENT ;
  recovery expression synchronize [";", "}"] ;
  diagnostic JCG-01251 when unexpected_token ;
}
validate parser Grammar01251 with lalr1
assert certificate.semantic_hash == "invalid-01251"

